const pageData = await browserjs(tabId, () => {
  // Check if there is preloaded state or global objects
  const keys = Object.keys(window).filter(k => k.toLowerCase().includes('state') || k.toLowerCase().includes('data') || k.toLowerCase().includes('ikea'));

  // Check product cards in DOM
  const productCards = Array.from(document.querySelectorAll('.plp-fragment-wrapper, .pip-product-compact, [data-testid="plp-product-card"]')).map(el => {
    return {
      title: el.querySelector('.pip-header-section__title--small, .pip-compact-price-package__title, h3')?.textContent.trim(),
      desc: el.querySelector('.pip-header-section__description-text, .pip-compact-price-package__description')?.textContent.trim(),
      price: el.querySelector('.pip-price__integer, .pip-compact-price-package__price')?.textContent.trim(),
      rating: el.querySelector('.pip-rating, [aria-label*="star"], [aria-label*="out of 5"]')?.getAttribute('aria-label') || el.querySelector('.pip-rating')?.textContent.trim(),
      link: el.querySelector('a')?.href
    };
  });

  return { keys, productCardsCount: productCards.length, sampleCards: productCards.slice(0, 5) };
